class Solution:
    def popcountDepth(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        small = [0] * 64
        for x in range(2, 64):
            small[x] = small[bin(x).count('1')] + 1
        def dep(v):
            return 0 if v == 1 else small[bin(v).count('1')] + 1
        K = 6
        bits = [[0] * (n + 1) for _ in range(K)]
        def upd(k, i, d):
            i += 1
            while i <= n:
                bits[k][i] += d
                i += i & -i
        def sm(k, i):
            i += 1; s = 0
            while i > 0:
                s += bits[k][i]
                i -= i & -i
            return s
        d = [dep(v) for v in nums]
        for i, x in enumerate(d):
            upd(x, i, 1)
        res = []
        for q in queries:
            if q[0] == 1:
                _, l, r, k = q
                res.append(sm(k, r) - sm(k, l - 1))
            else:
                _, idx, val = q
                upd(d[idx], idx, -1)
                d[idx] = dep(val)
                upd(d[idx], idx, 1)
        return res

