class Solution {
public:
    vector<int> popcountDepth(vector<long long>& nums, vector<vector<long long>>& queries) {
        int n = nums.size();
        int small[64] = {0};
        for (int x = 2; x < 64; x++) small[x] = small[__builtin_popcount(x)] + 1;
        auto dep = [&](long long v) -> int {
            return v == 1 ? 0 : small[__builtin_popcountll(v)] + 1;
        };
        int K = 6;
        vector<array<int, 100005>> bits;
        // use vector<vector<int>> sized n+1
        vector<vector<int>> tr(K, vector<int>(n + 1, 0));
        auto upd = [&](int k, int i, int d) {
            for (i++; i <= n; i += i & -i) tr[k][i] += d;
        };
        auto sm = [&](int k, int i) {
            int s = 0;
            for (i++; i > 0; i -= i & -i) s += tr[k][i];
            return s;
        };
        vector<int> d(n);
        for (int i = 0; i < n; i++) { d[i] = dep(nums[i]); upd(d[i], i, 1); }
        vector<int> res;
        for (auto& q : queries) {
            if (q[0] == 1) {
                int l = q[1], r = q[2], k = q[3];
                res.push_back(sm(k, r) - sm(k, l - 1));
            } else {
                int idx = q[1]; long long val = q[2];
                upd(d[idx], idx, -1);
                d[idx] = dep(val);
                upd(d[idx], idx, 1);
            }
        }
        return res;
    }
};

