class Solution {
    public int[] popcountDepth(long[] nums, int[][] queries) {
        int n = nums.length;
        int[] small = new int[64];
        for (int x = 2; x < 64; x++) small[x] = small[Long.bitCount(x)] + 1;
        int[][] tr = new int[6][n + 1];
        int[] d = new int[n];
        for (int i = 0; i < n; i++) {
            long v = nums[i];
            d[i] = v == 1 ? 0 : small[Long.bitCount(v)] + 1;
            for (int j = i + 1; j <= n; j += j & -j) tr[d[i]][j]++;
        }
        int[] res = new int[queries.length]; int ri = 0;
        for (int[] q : queries) {
            if (q[0] == 1) {
                int l = q[1], r = q[2], k = q[3], s = 0;
                for (int i = r + 1; i > 0; i -= i & -i) s += tr[k][i];
                for (int i = l; i > 0; i -= i & -i) s -= tr[k][i];
                res[ri++] = s;
            } else {
                int idx = q[1]; long val = q[2];
                int old = d[idx];
                for (int j = idx + 1; j <= n; j += j & -j) tr[old][j]--;
                int nd = val == 1 ? 0 : small[Long.bitCount(val)] + 1;
                d[idx] = nd;
                for (int j = idx + 1; j <= n; j += j & -j) tr[nd][j]++;
            }
        }
        return res;
    }
}

