var popcountDepth = function(nums, queries) {
    const n = nums.length;
    const bc = v => { let c = 0; while (v) { v &= v - 1n; c++; } return c; };
    const small = Array(64).fill(0);
    for (let x = 2; x < 64; x++) small[x] = small[bc(BigInt(x))] + 1;
    const dep = v => v === 1n ? 0 : small[bc(v)] + 1;
    const tr = Array.from({length: 6}, () => Array(n + 1).fill(0));
    const d = nums.map(dep);
    const upd = (k, i, dl) => { for (i++; i <= n; i += i & -i) tr[k][i] += dl; };
    const sm = (k, i) => { let s = 0; for (i++; i > 0; i -= i & -i) s += tr[k][i]; return s; };
    d.forEach((x, i) => upd(x, i, 1));
    const res = [];
    for (const q of queries) {
        if (q[0] === 1) {
            const [, l, r, k] = q;
            res.push(sm(k, r) - sm(k, l - 1));
        } else {
            const [, idx, val] = q;
            upd(d[idx], idx, -1);
            d[idx] = dep(BigInt(val));
            upd(d[idx], idx, 1);
        }
    }
    return res;
};
